func commitCountLabel(n int) string {
	if n == 1 {
		return "1 commit"
	}
	return strconv.Itoa(n) + " commits"
}

func moreCommitsLabel(n int) string {
	if n == 1 {
		return "and 1 more commit"
	}
	return "and " + strconv.Itoa(n) + " more commits"
}

func actorInitials(name string) string {
	r := []rune(name)
	switch {
	case len(r) == 0:
		return "?"
	case len(r) == 1:
		return string(r[:1])
	default:
		return string(r[:2])
	}
}

func activityVerb(kind string) string {
	switch kind {
	case "push":
		return "pushed"
	case "pr_opened":
		return "opened"
	case "pr_merged":
		return "merged"
	case "pr_closed":
		return "closed"
	case "issue_opened":
		return "opened"
	case "issue_closed":
		return "closed"
	case "comment":
		return "commented on"
	case "star":
		return "starred"
	case "release", "release_published":
		return "released"
	case "fork":
		return "forked"
	case "member_added":
		return "added member"
	}
	return "updated"
}

